 "content": "def _runs(active):
    runs = []
    start = None
    for i, value in enumerate(active):
        if value and start is None:
            start = i
        elif not value and start is not None:
            runs.append((start, i - 1))
            start = None
    if start is not None:
        runs.append((start, len(active) - 1))
    return runs


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_runs = _runs([any(grid[r][c] != 0 for c in range(w)) for r in range(h)])
    col_runs = _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])

    # Each nonzero rectangle is a tile; its one-cell border is the frame,
    # while the interior contains the repeated symbol being connected.
    counts = {}
    interiors = {}
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            ys = list(range(r0 + 1, r1))
            xs = list(range(c0 + 1, c1))
            interiors[ri, ci] = (ys, xs)
            for r in ys:
                for c in xs:
                    color = grid[r][c]
                    if color:
                        counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    common = max(counts, key=counts.get)
    signals = set(counts) - {common}

    # Join repeated non-background interior colors along each tile row,
    # filling only the zero-valued separator cells and preserving all tiles.
    for ri in range(len(row_runs)):
        for color in signals:
            for yoff in range(max((len(interiors[ri, ci][0]) for ci in range(len(col_runs))), default=0)):
                for xoff in range(max((len(interiors[ri, ci][1]) for ci in range(len(col_runs))), default=0)):
                    positions = []
                    for ci, (c0, c1) in enumerate(col_runs):
                        ys, xs = interiors[ri, ci]
                        if yoff < len(ys) and xoff < len(xs) and grid[ys[yoff]][xs[xoff]] == color:
                            positions.append(xs[xoff])
                    for left, right in zip(positions, positions[1:]):
                        r = row_runs[ri][0] + 1 + yoff
                        for c in range(left + 1, right):
                            if out[r][c] == 0:
                                out[r][c] = color

    # Join vertically repeated symbols in the analogous way.
    for ci in range(len(col_runs)):
        for color in signals:
            max_y = max((len(interiors[ri, ci][0]) for ri in range(len(row_runs))), default=0)
            max_x = max((len(interiors[ri, ci][1]) for ri in range(len(row_runs))), default=0)
            for yoff in range(max_y):
                for xoff in range(max_x):
                    positions = []
                    for ri, (r0, r1) in enumerate(row_runs):
                        ys, xs = interiors[ri, ci]
                        if yoff < len(ys) and xoff < len(xs) and grid[ys[yoff]][xs[xoff]] == color:
                            positions.append(ys[yoff])
                    for top, bottom in zip(positions, positions[1:]):
                        c = col_runs[ci][0] + 1 + xoff
                        for r in range(top + 1, bottom):
                            if out[r][c] == 0:
                                out[r][c] = color
    return out
